import { Actor, Document } from './types';
import { DocumentRepository } from './repository';

export class DocumentService {
  constructor(private readonly repository: DocumentRepository) {}

  archive(actor: Actor, id: string): void {
    const document = this.repository.find(id);
    if (!document || document.deleted || document.tenant !== actor.tenant) {
      throw new Error('not found');
    }
    if (!this.isAuthorized(actor, document)) {
      throw new Error('forbidden');
    }
    if (!document.archived) {
      this.repository.archive(document, actor.user);
    }
  }

  private isAuthorized(actor: Actor, document: Document): boolean {
    switch (actor.role) {
      case 'admin':
        return true;
      case 'editor':
        return document.owner === actor.user;
      case 'viewer':
        return false;
    }
  }
}
